// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    address actor;

    function setUp() public {
        actor = makeAddr("actor");
        vm.prank(actor);
        c = new SimpleWallet();
    }

    function testFuzz_property(uint256 amount) public {
        amount = bound(amount, 1, 1000 ether);
        vm.assume(actor != address(c) && actor != address(this));
        vm.deal(address(c), amount);
        uint256 actorBefore = actor.balance;
        vm.prank(actor);
        c.withdrawAll();
        assertTrue(address(c).balance == 0 && actor.balance - actorBefore == amount);
    }
}
